"""Explain bounded stack strings and IRQ range/prefix filtering."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1965': ('긴 문장을 작은 메모지에 적으면 끝까지 담지 못해요. 적힌 양과 원래 적으려던 양은 다를 수 있어요.', '문자열의 실제 저장량과 snprintf의 반환 길이를 구별합니다.', '영문 아홉 글자를 다섯 칸에 넣는다고 해 보세요. 네 칸에는 글자, 마지막 한 칸에는 끝 표시를 적고 반환 길이 9를 따로 쓰세요.', ['stack_trace_snprint는 이미 모은 호출 경로 주소를 글자로 만들어 buf에 이어 써요. buf는 글자를 담을 메모리 위치이고 size는 남은 바이트 수예요. 바이트는 메모리 크기를 세는 단위예요. 이 예에서는 영문 글자 하나를 한 바이트로 세어요.', '안에서 부르는 snprintf는 주어진 공간 안에 문자열을 써요. 문자열 끝에는 값 0인 바이트, 즉 NUL 끝 표시가 필요해요. size=5라면 글자에 최대 네 바이트를 쓰고 마지막 한 바이트를 끝 표시에 남겨요. 한글의 글자 수와 바이트 수는 같지 않을 수 있어요.', 'snprintf의 반환값 generated는 공간이 충분했다면 만들어졌을 길이예요. 끝 표시 한 바이트는 이 길이에서 빼요. 따라서 한 줄에 아홉 바이트가 필요했다면 다섯 바이트 공간에 일부만 써도 generated는 9예요.', 'wrapper는 generated를 total에 더해요. total은 처음 0이므로 이 예에서는 0+9=9가 돼요. 저장한 글자는 네 바이트인데 반환값은 9인 이유예요. 이 수를 실제로 읽을 수 있는 버퍼 길이라고 곧바로 사용하면 안 돼요.', 'generated >= size이면 공간이 부족해 잘렸다는 뜻이에요. 두 값이 같아도 끝 표시를 넣을 한 칸이 부족하므로 잘려요. 코드는 남은 size를 0으로 만들고 다음 반복을 멈춰요. 첫 줄 다음에 다른 주소가 있어도 그 줄의 길이는 계산하지 않아요.', '그러므로 total은 모든 주소를 출력하는 데 필요한 전체 길이를 언제나 알려 주는 값이 아니에요. 첫 줄 길이 9, 둘째 줄 길이 7인 가상 예에서 공간이 첫 줄에서 끝나면 16이 아니라 9예요. 여기서 정한 줄 길이는 계산 연습용이며 실제 주소 출력 길이를 고정한 것이 아니에요.'], [('첫 줄에 아홉 바이트가 필요하고 버퍼가 다섯 바이트라면 total은 얼마인가요?', ['실제로 담긴 글자 양인 4예요', 'snprintf가 알려 준 필요 길이인 9예요'], '정답은 두 번째예요. 코드가 generated를 total에 더하기 때문이에요. 실제 저장 공간에는 글자 네 바이트와 끝 표시가 들어가도 generated는 9예요.'), ('첫 줄에서 남은 size가 0이 되면 둘째 줄 이후의 필요 길이도 계산하나요?', ['아니요. 반복이 끝나서 계산하지 않아요', '네. 모든 줄을 끝까지 계산해요'], '정답은 첫 번째예요. 반복 조건에 size가 있어 0이면 다음 줄에 들어가지 않아요. 반환값을 목록 전체의 필요 공간으로 해석하면 안 되는 이유예요.')]), 'os1966': ('공책에 문장을 이어 쓰려면 다음에 쓸 자리와 남은 칸 수를 함께 바꿔야 해요. 둘 중 하나만 바꾸면 같은 곳을 덮거나 공간을 넘을 수 있어요.', '출력 위치 이동과 남은 공간 감소, 크기 0의 동작을 이해합니다.', '열 칸 중 첫 줄이 세 바이트라면 다음 위치는 3, 남은 크기는 7이라고 쓰세요. 다음 줄이 두 바이트라면 위치 5, 남은 크기 5예요.', ['buf는 다음 글자를 쓸 위치이고 size는 그 위치부터 남아 있는 공간이에요. stack_trace_snprint는 주소 한 개를 한 줄로 바꾸어 쓰고 이 두 정보를 갱신해요. 포인터는 이런 메모리 위치를 담는 값이에요.', '한 줄이 끝 표시까지 들어가려면 generated < size여야 해요. 예를 들어 열 바이트에 세 바이트짜리 줄을 쓰면 buf += generated로 위치를 세 바이트 앞으로 옮기고 size -= generated로 남은 공간을 7로 줄여요.', '첫 줄의 끝 표시는 원래 시작점에서 3번 위치에 있어요. 다음 출력은 그 끝 표시 자리에 새 글자를 쓰며 이어지고, 새 줄 끝에 다시 끝 표시를 붙여요. 끝 표시까지 건너뛰어 빈틈을 남기는 방식이 아니에요.', '두 번째 줄이 두 바이트라면 출력 뒤 위치는 처음에서 5바이트 앞으로 가고 남은 크기는 5가 돼요. 기록한 내용은 합쳐서 다섯 바이트이고 끝 표시는 그다음 자리에 있어요. 예시의 줄 길이에는 줄바꿈도 포함한다고 정해 계산해요.', '처음 size가 0이면 반복 조건부터 맞지 않아 snprintf를 한 번도 부르지 않고 total=0을 반환해요. snprintf 자체의 크기 0 호출을 이용하면 길이를 구할 수 있다는 다른 사용법을 이 wrapper에도 그대로 적용할 수는 없어요.', '출력을 하지 않은 경로에서는 버퍼에 끝 표시를 새로 써 주지도 않아요. 처음부터 size=0이거나 항목 개수가 0인 경우가 그래요. 실제로 쓸 때는 필요한 크기의 유효한 버퍼와 읽을 수 있는 주소 배열을 준비하고, 함수가 어떤 경로를 실행했는지에 맞춰 결과를 사용해요.'], [('처음부터 size=0이면 이 wrapper가 snprintf를 불러 전체 길이를 구하나요?', ['네. 크기가 0이어도 모두 계산해요', '아니요. 출력 반복 없이 0을 반환해요'], '정답은 두 번째예요. for 조건에서 size가 0이라 본문을 건너뛰어요. snprintf를 직접 부르는 사용법과 wrapper가 그 함수를 부르는 조건을 구별해요.'), ('한 줄의 generated가 3이고 남은 공간 10에 온전히 들어갔다면 다음 출력 위치는 얼마나 움직이나요?', ['3바이트 앞으로 움직이고 남은 크기는 7이 돼요', '10바이트 앞으로 움직여 공간을 전부 건너뛰어요'], '정답은 첫 번째예요. 성공 분기는 generated만큼 이동하고 같은 양을 남은 크기에서 빼요. 전체 공간을 건너뛰면 다음 줄을 이어 쓸 자리를 잃게 돼요.')]), 'os1967': ('주소 번호가 두 구역 중 어디에 속하는지 확인해 봐요. 구역의 시작 번호는 들어가고 끝 경계 번호는 그 구역에 들어가지 않아요.', '시작은 포함하고 끝은 제외하는 범위와 두 범위의 OR를 이해합니다.', '첫 구역 [100,116), 둘째 구역 [116,132)를 그리세요. 100·115·116·132가 어느 구역에 들어가는지 표시하세요.', ['IRQ는 장치 같은 곳에서 CPU에 처리가 필요한 사건을 알리는 요청이에요. 커널에는 하드 IRQ 진입 코드와 softirq 진입 코드의 영역을 표시하는 경계가 있어요. softirq는 커널이 일부 처리를 나누어 수행하는 방식이에요.', 'in_irqentry_text는 받은 주소 ptr가 이 두 코드 영역 중 하나에 속하는지 확인해요. 여기서 section은 코드가 모여 있는 구역이라고 생각하면 돼요. 시작과 끝 이름은 그 구역의 경계 위치를 나타내요.', 'ptr >= start는 시작 이상인지, ptr < end는 끝보다 작은지 묻는 식이에요. &&는 두 조건이 모두 맞아야 참이라는 뜻이에요. 따라서 시작은 포함하고 끝은 제외해요. 이를 [start,end)라고 쓰는데 대괄호는 포함, 소괄호는 제외를 나타내요.', '연습용 주소로 [100,116)을 정하면 100과 115는 들어가고 116은 빠져요. 정수 주소 위치를 세면 100부터 115까지 열여섯 개예요. 끝을 다음 구역의 시작 경계로 삼으면 같은 위치를 양쪽 구역에 중복해 넣지 않을 수 있어요.', '코드는 두 구역의 판단을 ||로 연결해요. ||는 어느 하나라도 맞으면 참인 OR예요. 둘째 구역이 [116,132)라면 116은 첫째에는 없지만 둘째에는 있으므로 전체 결과는 참이에요. 132는 이 예의 두 구역 모두에서 빠져요.', '이 숫자 배치는 연습을 위한 가정이에요. 실제 두 영역이 반드시 붙어 있다는 뜻은 아니에요. 실제 경계는 커널을 만드는 연결 과정에서 정해져요. 함수는 주어진 경계와 주소를 비교할 뿐 IRQ를 발생시키거나 모든 스택 내용의 정확성을 검사하지는 않아요.'], [('[100,116)이라는 범위에 시작 주소 100이 들어가나요?', ['아니요. 시작은 항상 제외해요', '네. 시작은 포함해요'], '정답은 두 번째예요. 100>=100과 100<116이 모두 맞아요. 끝 116에만 < 비교를 쓰므로 시작과 끝의 규칙이 달라요.'), ('첫 구역 [100,116), 둘째 구역 [116,132)에서 주소 116의 전체 판정은 무엇인가요?', ['둘째 구역에 들어가므로 참이에요', '첫 구역의 끝이므로 무조건 거짓이에요'], '정답은 첫 번째예요. 첫 구역은 거짓이지만 둘째 구역은 참이에요. 거짓 OR 참은 참이므로 한 구역에서 제외된다는 사실만으로 전체를 판단하면 안 돼요.')]), 'os1968': ('주소 카드가 여러 장 있을 때 특별한 표시가 처음 나타난 카드까지 골라 봐요. 그 카드를 포함해 몇 장인지 알려 주되 카드를 찢거나 옮기지는 않아요.', '첫 IRQ 진입 주소를 포함한 개수를 반환하는 필터를 이해합니다.', '0번 A, 1번 IRQ 진입, 2번 B를 그리세요. 0번과 1번을 묶어 두 개라고 쓰고 세 카드 자체는 그대로 두세요.', ['filter_irq_stacks는 모아 둔 스택 주소 배열에서 처음 나타나는 IRQ 진입 주소를 찾아요. 앞 수업의 in_irqentry_text를 사용해 주소가 해당 코드 구역 안에 있는지 확인해요.', '배열 번호 i는 0부터 시작해요. 첫 칸은 0번, 둘째 칸은 1번이에요. nr_entries는 조사할 주소 개수이며, i가 그보다 작은 동안 앞에서 뒤로 확인해요.', 'IRQ 진입 주소를 처음 찾으면 return i + 1로 바로 끝나요. 원문 주석은 그 진입 함수도 포함하라고 설명해요. 따라서 1번 위치에서 찾으면 0번과 1번 두 항목을 사용하도록 2를 돌려줘요.', '첫 칸 0번에서 찾으면 결과는 1이에요. 0개가 아니에요. 마지막 2번에서 처음 찾는 세 항목 예에서는 결과가 3이에요. 번호와 포함할 개수가 하나 차이 나는 이유는 번호가 0부터 시작하기 때문이에요.', '아무 IRQ 진입 주소도 없으면 반복이 끝나고 원래 nr_entries를 반환해요. 세 항목에 없다면 3이고 처음부터 항목이 0개라면 반복하지 않고 0이에요. 못 찾았다고 모든 기록을 버리는 규칙은 아니에요.', '이 함수는 배열 내용을 지우거나 옮기지 않고 사용할 앞부분의 개수만 알려 줘요. 부른 쪽이 그 반환 개수를 사용해야 뒤쪽 항목을 제외할 수 있어요. 이름이 filter라고 해서 배열 자체가 짧아지거나 남은 메모리가 해제되는 것은 아니에요.'], [('첫 IRQ 진입 주소가 배열 1번 위치에 있다면 반환 개수는 얼마인가요?', ['1개예요', '2개예요'], '정답은 두 번째예요. 0번과 1번을 함께 포함하므로 i+1=1+1=2예요. 1은 위치 번호이고 2는 포함할 주소 개수예요.'), ('세 주소 중 IRQ 진입 주소가 하나도 없다면 배열을 비우나요?', ['아니요. 배열은 그대로이고 원래 개수 3을 반환해요', '네. 배열을 지우고 항상 0을 반환해요'], '정답은 첫 번째예요. 반복 뒤의 return nr_entries로 3을 돌려줘요. 배열을 바꾸는 저장 명령도 없으므로 필터라는 이름만 보고 삭제를 떠올리면 안 돼요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_487.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
